        /**
          * Brouillon de chaque liste de sources (champ « nouvelle source »).
          * @default {}
         */
        "drafts"?: Record<string, string> | string;
        /**
          * Libellé affiché devant chaque entrée d'une liste de sources (« Dossier », « Réseau »…), par valeur.
          * @default {}
         */
